CREATE OR REPLACE PROCEDURE public.sp_save_child_care_supply_status(IN p_id uuid, IN p_tenant_id uuid, IN p_organization_id uuid, IN p_branch_id uuid, IN p_classroom_id uuid, IN p_child_id uuid, IN p_supply_type character varying, IN p_status character varying, IN p_notes text, IN p_threshold_note character varying, IN p_last_reported_by_user_id uuid, IN p_last_reported_by_name character varying, IN p_parent_reminder_sent boolean, IN p_last_reminder_at timestamp with time zone, IN p_created_at timestamp with time zone, IN p_updated_at timestamp with time zone)  LANGUAGE plpgsql AS $procedure$ BEGIN     INSERT INTO child_care_supplies (         id, tenant_id, organization_id, branch_id, classroom_id, child_id,         supply_type, status, notes, threshold_note, last_reported_by_user_id,         last_reported_by_name, parent_reminder_sent, last_reminder_at, created_at, updated_at     ) VALUES (         p_id, p_tenant_id, p_organization_id, p_branch_id, p_classroom_id, p_child_id,         p_supply_type, p_status, p_notes, p_threshold_note, p_last_reported_by_user_id,         p_last_reported_by_name, p_parent_reminder_sent, p_last_reminder_at, p_created_at, p_updated_at     )     ON CONFLICT (id) DO UPDATE     SET status = EXCLUDED.status,         notes = EXCLUDED.notes,         threshold_note = EXCLUDED.threshold_note,         last_reported_by_user_id = EXCLUDED.last_reported_by_user_id,         last_reported_by_name = EXCLUDED.last_reported_by_name,         parent_reminder_sent = EXCLUDED.parent_reminder_sent,         last_reminder_at = EXCLUDED.last_reminder_at,         updated_at = EXCLUDED.updated_at; END; $procedure$ ;
